package dev.hrutvik.billing.metering;
import com.fasterxml.jackson.databind.ObjectMapper; import dev.hrutvik.billing.outbox.*; import dev.hrutvik.billing.usage.*; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.time.*; import java.util.*; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.Mockito.*;
class UsageAggregationServiceTest {
 @Test void recordsInboxBeforeUpdatingSubscriptionBucket(){var events=mock(UsageEventRepository.class);var store=mock(MeteringStore.class);var outbox=mock(OutboxEventRepository.class);var now=Instant.parse("2026-11-03T12:15:00Z");var id=UUID.randomUUID();var subscription=UUID.randomUUID();var usage=new UsageEvent(id,"tenant-a",subscription,"external-1","hash","api_calls",new BigDecimal("2.50"),Instant.parse("2026-11-03T10:47:11Z"),now,"{}");when(events.findById(id)).thenReturn(Optional.of(usage));when(store.recordInbox(id,"usage",2,41,now)).thenReturn(true);var service=new UsageAggregationService(events,store,outbox,new ObjectMapper(),Clock.fixed(now,ZoneOffset.UTC));assertThat(service.aggregate(id,"usage",2,41)).isTrue();verify(store).addToBucket("tenant-a",subscription,"api_calls",Instant.parse("2026-11-03T10:00:00Z"),new BigDecimal("2.50"),now);}
 @Test void duplicateDeliveryDoesNotDoubleCount(){var events=mock(UsageEventRepository.class);var store=mock(MeteringStore.class);var outbox=mock(OutboxEventRepository.class);var id=UUID.randomUUID();var usage=new UsageEvent(id,"tenant-a",UUID.randomUUID(),"external-1","hash","api_calls",BigDecimal.ONE,Instant.now(),Instant.now(),"{}");when(events.findById(id)).thenReturn(Optional.of(usage));when(store.recordInbox(eq(id),any(),anyInt(),anyLong(),any())).thenReturn(false);var service=new UsageAggregationService(events,store,outbox,new ObjectMapper(),Clock.systemUTC());assertThat(service.aggregate(id,"usage",0,8)).isFalse();verify(store,never()).addToBucket(any(),any(),any(),any(),any(),any());verifyNoInteractions(outbox);}
 @Test void lateUsageCreatesAdjustmentAndOutboxEventAtomically(){var events=mock(UsageEventRepository.class);var store=mock(MeteringStore.class);var outbox=mock(OutboxEventRepository.class);var now=Instant.parse("2026-11-08T12:00:00Z");var received=Instant.parse("2026-11-08T11:00:00Z");var occurred=Instant.parse("2026-10-20T10:15:00Z");var id=UUID.randomUUID();var subscription=UUID.randomUUID();var invoice=new MeteringStore.FinalizedInvoice(UUID.randomUUID(),"INV-100","USD",Instant.parse("2026-10-01T00:00:00Z"),Instant.parse("2026-11-01T00:00:00Z"));var usage=new UsageEvent(id,"tenant-a",subscription,"late-1","hash","api_calls",new BigDecimal("25"),occurred,received,"{}");when(events.findById(id)).thenReturn(Optional.of(usage));when(store.recordInbox(any(),any(),anyInt(),anyLong(),any())).thenReturn(true);when(store.finalizedInvoiceFor("tenant-a",subscription,occurred,received)).thenReturn(Optional.of(invoice));when(store.recordLateAdjustment(any(),eq(invoice),eq("tenant-a"),eq(subscription),eq(id),eq("api_calls"),eq(new BigDecimal("25")),eq(occurred),eq(now))).thenReturn(true);var service=new UsageAggregationService(events,store,outbox,new ObjectMapper(),Clock.fixed(now,ZoneOffset.UTC));assertThat(service.aggregate(id,"usage",1,9)).isTrue();verify(outbox).save(argThat(e->"LATE_USAGE_DETECTED".equals(e.getEventType())&&"billing.late-usage-detected.v1".equals(e.getDestination())));}
}
